import { useId, useState } from 'react'
import './styles.css'

export interface MultiSelectOption {
  value: string
  label: string
}

export interface MultiSelectProps {
  options: MultiSelectOption[]
  values: string[]
  onChange: (values: string[]) => void
  label: string
  selectedLabel?: string
  clearLabel?: string
  className?: string
}

export function MultiSelect({
  options,
  values,
  onChange,
  label,
  selectedLabel = 'selected',
  clearLabel = 'Clear all',
  className,
}: MultiSelectProps) {
  const [open, setOpen] = useState(false)
  const listboxId = useId()
  const classes = ['cu-multi-select', className].filter(Boolean).join(' ')

  const toggle = (value: string) => {
    onChange(values.includes(value) ? values.filter((entry) => entry !== value) : [...values, value])
  }

  const labelFor = (value: string) => options.find((option) => option.value === value)?.label ?? value

  return (
    <div className={classes} data-ai-role="multi-select" data-ai-intent="toggle-option" data-ai-state={open ? 'open' : values.length === 0 ? 'empty' : 'default'}>
      <span className="cu-multi-select__label" id={`${listboxId}-label`}>
        {label}
      </span>
      {values.length > 0 ? (
        <ul className="cu-multi-select__chips" aria-label={`${values.length} ${selectedLabel}`}>
          {values.map((value) => (
            <li key={value} className="cu-multi-select__chip">
              <span>{labelFor(value)}</span>
              <button
                type="button"
                className="cu-multi-select__chip-remove"
                aria-label={`${clearLabel}: ${labelFor(value)}`}
                onClick={() => toggle(value)}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      ) : null}
      <button
        type="button"
        className="cu-multi-select__trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-labelledby={`${listboxId}-label`}
        onClick={() => setOpen((current) => !current)}
      >
        {values.length > 0 ? `${values.length} ${selectedLabel}` : label}
        <span aria-hidden="true"> ▾</span>
      </button>
      {open ? (
        <ul
          className="cu-multi-select__listbox"
          role="listbox"
          aria-multiselectable="true"
          aria-labelledby={`${listboxId}-label`}
          id={listboxId}
          onKeyDown={(event) => {
            if (event.key === 'Escape') setOpen(false)
          }}
        >
          {options.map((option) => {
            const selected = values.includes(option.value)
            return (
              <li
                key={option.value}
                className="cu-multi-select__option"
                role="option"
                aria-selected={selected}
                tabIndex={0}
                onClick={() => toggle(option.value)}
                onKeyDown={(event) => {
                  if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault()
                    toggle(option.value)
                  }
                }}
              >
                <span className="cu-multi-select__check" aria-hidden="true">
                  {selected ? '✓' : ''}
                </span>
                {option.label}
              </li>
            )
          })}
        </ul>
      ) : null}
    </div>
  )
}

.cu-multi-select {
  position: relative;
  display: inline-block;
  min-inline-size: calc(var(--cu-space-3) * 16);
  color: var(--cu-color-fg-default);
}

.cu-multi-select__label {
  display: block;
  margin-block-end: var(--cu-space-1);
  font-size: 0.875em;
}

.cu-multi-select__chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cu-space-1);
  list-style: none;
  margin: 0 0 var(--cu-space-1);
  padding: 0;
}

.cu-multi-select__chip {
  display: inline-flex;
  align-items: center;
  gap: var(--cu-space-1);
  padding-block: calc(var(--cu-space-1) / 2);
  padding-inline: var(--cu-space-2);
  border-radius: var(--cu-radius-md);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
}

.cu-multi-select__chip-remove {
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-multi-select__trigger {
  display: flex;
  justify-content: space-between;
  align-items: center;
  inline-size: 100%;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-multi-select__trigger:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-multi-select__listbox {
  position: absolute;
  z-index: 1;
  inset-inline: 0;
  margin: var(--cu-space-1) 0 0;
  padding: var(--cu-space-1);
  list-style: none;
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  max-block-size: calc(var(--cu-space-3) * 16);
  overflow-y: auto;
}

.cu-multi-select__option {
  display: flex;
  align-items: center;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border-radius: var(--cu-radius-sm);
  cursor: pointer;
}

.cu-multi-select__option[aria-selected='true'] {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
}

.cu-multi-select__option:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-multi-select__check {
  inline-size: var(--cu-space-2);
}
